import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"模块边界与分层策略","description":"","frontmatter":{"title":"模块边界与分层策略","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/architecture/modularization.md","filePath":"frontend/decisions/architecture/modularization.md","lastUpdated":1785589115000}'),n={name:"frontend/decisions/architecture/modularization.md"};function s(i,t,l,o,h,p){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="模块边界与分层策略" tabindex="-1">模块边界与分层策略 <a class="header-anchor" href="#模块边界与分层策略" aria-label="Permalink to &quot;模块边界与分层策略&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>模块化不是把文件放进更多目录，而是控制变更传播：谁拥有业务规则、哪些依赖被允许、一个需求会迫使多少无关代码一起修改。本章只讨论边界策略的选择；具体的依赖方向、目录和约束实现参见<a href="/frontend/guide/engineering/architecture/layers-modules">分层、模块边界与依赖方向</a>。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>小型应用可以依靠组件和几个公共目录保持清楚。随着业务和团队增长，<code>components</code>、<code>utils</code>、<code>services</code> 往往成为所有模块共享的隐式中心，任何修改都需要全局回归。相反，过早拆出大量包会增加配置、发布和跨包调试成本。</p><p>决策问题不是“是否模块化”，而是当前需要多强的边界，以及边界按技术职责还是业务变化原因划分。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-必须保持的约束" tabindex="-1">2.1 必须保持的约束 <a class="header-anchor" href="#_2-1-必须保持的约束" aria-label="Permalink to &quot;2.1 必须保持的约束&quot;">​</a></h3><ul><li>认证、支付等敏感逻辑必须通过受控入口访问；</li><li>公共包不能反向依赖具体业务；</li><li>浏览器代码不能意外引入服务端密钥或 Node.js 专用模块；</li><li>每个持久化数据和远程接口必须有明确所有者；</li><li>循环依赖和越层访问应能被自动检查，而非只写在文档中。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较策略时关注：需求变更是否局部、团队能否独立理解、公共 API 数量、构建与测试反馈、跨边界调用成本、迁移成本和边界治理能力。</p><p>“目录看起来整齐”不是有效指标。可观察信号包括跨模块修改文件数、循环依赖数、公共模块变更影响范围和新人完成首个需求所需时间。</p><h2 id="_3-候选策略" tabindex="-1">3. 候选策略 <a class="header-anchor" href="#_3-候选策略" aria-label="Permalink to &quot;3. 候选策略&quot;">​</a></h2><h3 id="_3-1-按技术层组织" tabindex="-1">3.1 按技术层组织 <a class="header-anchor" href="#_3-1-按技术层组织" aria-label="Permalink to &quot;3.1 按技术层组织&quot;">​</a></h3><p>把页面、组件、请求、状态和工具分别集中。它简单、易于起步，适合规模小、业务域少且由同一团队维护的应用。随着业务增长，一个功能会横跨多个顶层目录，领域所有权不再直观。</p><h3 id="_3-2-按业务特性组织" tabindex="-1">3.2 按业务特性组织 <a class="header-anchor" href="#_3-2-按业务特性组织" aria-label="Permalink to &quot;3.2 按业务特性组织&quot;">​</a></h3><p>以订单、客户、库存等变化原因聚合页面、状态、请求和测试，并设置少量共享层。它能让需求修改局部化，适合业务域已经稳定的中大型应用。代价是需要判断哪些能力真正共享，并防止特性之间随意穿透。</p><h3 id="_3-3-领域模块与强制分层" tabindex="-1">3.3 领域模块与强制分层 <a class="header-anchor" href="#_3-3-领域模块与强制分层" aria-label="Permalink to &quot;3.3 领域模块与强制分层&quot;">​</a></h3><p>每个领域通过公开入口暴露能力，内部再区分 UI、应用编排、领域规则和基础设施；依赖由静态规则强制。适合多个团队、合规边界或长生命周期系统，但会增加抽象、测试替身和跨领域协调成本。</p><h3 id="_3-4-独立包边界" tabindex="-1">3.4 独立包边界 <a class="header-anchor" href="#_3-4-独立包边界" aria-label="Permalink to &quot;3.4 独立包边界&quot;">​</a></h3><p>将稳定能力拆为工作区包，可以独立构建、测试或发布。包边界比目录边界更强，但不是默认升级路径。若没有独立消费者、版本生命周期或权限要求，包只会制造额外维护面。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>技术分层</th><th>特性模块</th><th>强领域模块</th><th>独立包</th></tr></thead><tbody><tr><td>起步成本</td><td>低</td><td>中</td><td>高</td><td>高</td></tr><tr><td>业务变更局部性</td><td>低至中</td><td>高</td><td>高</td><td>高</td></tr><tr><td>跨模块契约</td><td>弱</td><td>中</td><td>强</td><td>最强</td></tr><tr><td>独立版本需求</td><td>不支持</td><td>通常不需要</td><td>可选</td><td>支持</td></tr><tr><td>治理要求</td><td>低</td><td>中</td><td>高</td><td>高</td></tr><tr><td>适合规模</td><td>小型</td><td>中大型单应用</td><td>多团队复杂领域</td><td>多消费者或独立生命周期</td></tr></tbody></table><p>强边界并不自动产生好架构。如果领域划分错误，强制包和接口只会把错误固化得更深。</p><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例是一个由 10 名开发者维护的 Vue 3 运营平台，包含订单、库存、客户和报表四个稳定业务域，共用身份、设计系统和 API 客户端；所有功能同一节奏发布。</p><p>推荐采用特性模块，并在模块内部按职责分层：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>  app/          # 应用装配、路由和全局提供者</span></span>
<span class="line"><span>  features/</span></span>
<span class="line"><span>    orders/</span></span>
<span class="line"><span>    inventory/</span></span>
<span class="line"><span>    customers/</span></span>
<span class="line"><span>    reports/</span></span>
<span class="line"><span>  shared/       # 无业务含义的稳定基础能力</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>每个特性只从公开 <code>index.ts</code> 导出页面入口和少量用例，禁止从其他特性的内部路径导入。暂不拆独立包，因为没有独立消费者或发布需求。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>收益是业务变更更局部、代码所有权清楚、可按特性运行测试。代价是团队必须维护公开入口、处理跨域需求，并接受部分看似重复的局部实现。</p><p>“共享”应以稳定语义和多个真实消费者为依据。为了消除三行重复而把业务差异塞进通用工具，会重新建立耦合中心。</p><p>退出成本主要来自模块公开 API 和路径规则。若需要合并模块，可在同一仓库内渐进调整；若已经拆成独立制品，还要处理版本、发布和兼容层。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>两三人的短期应用不需要完整领域分层和包发布。</li><li>业务边界仍高速变化时，不宜过早创建难以移动的独立包。</li><li>仅靠目录命名、没有依赖检查和所有者的“分层”不会形成边界。</li><li>为追求绝对零重复而建立巨大 <code>shared</code>，会抵消特性模块的收益。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>运营平台代码如何分区，降低跨域修改</td></tr><tr><td>硬约束</td><td>敏感能力受控；无跨特性内部导入；浏览器与服务端代码隔离</td></tr><tr><td>候选</td><td>技术分层、特性模块、强领域模块、独立包</td></tr><tr><td>决定</td><td>按业务特性组织，模块内部轻量分层</td></tr><tr><td>自动约束</td><td>ESLint 边界规则、循环依赖检查、公开入口导入规则</td></tr><tr><td>暂不采用</td><td>独立包发布和完整 DDD 分层</td></tr><tr><td>验证指标</td><td>跨域修改比例、边界违规数、共享模块变更影响、测试反馈时间</td></tr><tr><td>接受代价</td><td>维护公开入口；允许少量局部重复</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>当某模块出现独立消费者、需要不同权限或发布节奏、跨模块修改持续超过需求文件的 40%，或 <code>shared</code> 变更频繁导致大范围回归时复查。若团队缩小、领域合并或强边界的维护成本连续两个季度高于收益，也应主动简化。</p>`,39)])])}const b=a(n,[["render",s]]);export{u as __pageData,b as default};
